sys_script_include.script:
var BillingUtils = Class.create();
BillingUtils.prototype = {
    initialize: function() {
    },
      getAllBillsByPatient: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_billing');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('number') + ';' + gr.getValue('u_total_amount') + ';' + gr.getValue('u_status') + '\n';
        }
        return result || false;
    },

    // 2. Get unpaid bills (u_status = 'Pending' or 'Unpaid')
    getUnpaidBills: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_billing');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_status', 'Pending'); // or 'Unpaid' depending on your system
        gr.query();
        while (gr.next()) {
            result += gr.getValue('number') + ';' + gr.getValue('u_total_amount') + '\n';
        }
        return result || false;
    },

    // 3. Get paid bills (u_status = 'Paid')
    getPaidBills: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_billing');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_status', 'Paid');
        gr.query();
        while (gr.next()) {
            result += gr.getValue('number') + ';' + gr.getValue('u_total_amount') + '\n';
        }
        return result || false;
    },

    // 4. Get billing details by billing number
    getBillingDetailsByNumber: function (billingNumber) {
        var gr = new GlideRecord('u_billing');
        gr.addQuery('number', billingNumber);
        gr.query();
        if (gr.next()) {
            return gr.getValue('number') + ';' + gr.getValue('u_total_amount') + ';' + gr.getValue('u_status');
        }
        return false;
    },

    // 5. Get total billed amount for patient
    getTotalBilledAmount: function (patientId) {
        var total = 0;
        var gr = new GlideRecord('u_billing');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            total += parseFloat(gr.getValue('u_total_amount') || 0);
        }
        return total.toString();
    },

    type: 'BillingUtils'
};
